import { expect, test, uniqueName } from "../../fixtures";

const examples = [
  { field: "name", value: "A" },
  { field: "category", value: "furniture" },
  { field: "contact_email", value: "not-an-email" },
] as const;

test.describe("Reject invalid vendor fields", () => {
  for (const { field, value } of examples) {
    test(`rejects ${field} set to ${JSON.stringify(value)}`, { tag: "@VEN-02" }, async ({ apiAs }) => {
      // Arrange: a valid vendor payload with only the one field under test made invalid
      const member = await apiAs("member");
      const payload: Record<string, unknown> = {
        name: uniqueName("Invalid Field Vendor"),
        category: "software",
        contact_email: "billing@vendor.test",
      };
      payload[field] = value;

      // Act
      const res = await member.post("/api/vendors", { data: payload });
      const text = await res.text();

      // Assert
      expect(res.status(), text).toBe(422);
      const body = JSON.parse(text);
      const errorCode = body?.error?.code ?? body?.code;
      expect(errorCode, text).toBe("validation_error");
      expect(text, `error should name the field "${field}"`).toContain(field);
    });
  }
});
